#!/usr/bin/env python3
"""Ten alternating process pairs; all inputs generated by the native probe."""
import hashlib
import json
from pathlib import Path
import statistics
import subprocess
import sys

ROOT = Path(__file__).resolve().parents[3]
OUT = Path(__file__).resolve().parent
binary = ROOT / 'target/first30-apng-probe/release/rrrah-apng-first30-probe'
cases = [(1,'valid'),(16,'valid'),(512,'valid'),(4096,'valid'),(512,'large'),
         (4096,'invalid'),(16,'truncated'),(512,'no_memory'),(512,'cancelled'),(1,'empty'),(4096,'alternating')]
records = []
summaries = []
def percentile(values, p):
    values = sorted(values)
    return values[min(len(values)-1, int((len(values)-1)*p + .999999))]
for count, case in cases:
    runs = []
    for pair in range(10):
        row = {}
        for variant in (['baseline','candidate'] if pair % 2 == 0 else ['candidate','baseline']):
            result = subprocess.run([str(binary), variant, str(count), case],
                                    capture_output=True, text=True, timeout=30, check=True)
            data = json.loads(result.stdout)
            data.update(pair=pair)
            row[variant] = data
            records.append(data)
            (OUT/'apng-raw.json').write_text(json.dumps(records,indent=2)+'\n')
        for key in ['ok','output_or_error_hash','managed_peak_bytes','final_managed_bytes','balanced_live_bytes']:
            assert row['baseline'][key] == row['candidate'][key], (count,case,key,row)
        assert row['baseline']['ok'] == (case in ['valid','large','alternating'])
        runs.append(row)
    stats = {}
    for variant in ['baseline','candidate']:
        rows = [r[variant] for r in runs]
        wall = [s['wall_ns'] for r in rows for s in r['samples']]
        cpu = [s['cpu_ns'] for r in rows for s in r['samples']]
        stats[variant] = dict(
            wall_median_ns=statistics.median(wall), wall_p95_ns=percentile(wall,.95),
            cpu_median_ns=statistics.median(cpu), cpu_p95_ns=percentile(cpu,.95),
            peak_rss_bytes=max(s['rss_peak_bytes'] for r in rows for s in r['samples']),
            allocation_calls=sorted(set(r['allocation_calls'] for r in rows)),
            realloc_calls=sorted(set(r['realloc_calls'] for r in rows)),
            tracked_peak_live_bytes=sorted(set(r['tracked_peak_live_bytes'] for r in rows)),
            managed_peak_bytes=sorted(set(r['managed_peak_bytes'] for r in rows)))
    ratios = [statistics.median(s['wall_ns'] for s in r['baseline']['samples']) /
              statistics.median(s['wall_ns'] for s in r['candidate']['samples']) for r in runs]
    item = dict(count=count,case=case,statistics=stats,paired_baseline_over_candidate=ratios,
                median_paired_ratio=statistics.median(ratios),candidate_wins=sum(v>1 for v in ratios))
    summaries.append(item)
    print(count,case,'ratio',round(item['median_paired_ratio'],4),'wins',item['candidate_wins'],flush=True)
    (OUT/'apng-summary.json').write_text(json.dumps(summaries,indent=2)+'\n')
(OUT/'apng-run.json').write_text(json.dumps(dict(
    binary_sha256=hashlib.sha256(binary.read_bytes()).hexdigest(),
    warmups_per_process=3, alternating_pairs=10,batches_per_process=10,workloads_per_batch=32,
    host=sys.platform,allocation_scope='one complete workload (two decodes for alternating, otherwise one) plus output/error fingerprint; balanced TLS Rust allocator counters',
    timing_scope='complete workload, black-box output and destruction; full pixel fingerprint excluded from timing',
    rss_scope='OS process peak RSS including fixture and warmups; baseline/candidate in separate fresh processes',
    limitations=['Warm in-memory input; not viewer latency or disk throughput.','Rust allocation accounting excludes native foreign allocations and transient allocator-internal realloc copies.','An unrelated compiler was active at experiment setup; no unrelated process stopped.']),indent=2)+'\n')
